customCSS:
.t, .history { color: #b362ff; }
.join { color: #a5ff90; }
.part, .quit { color: #b362ff; }
.kick, .error { color: #ec3a37; }
.notice { color: #fad000; }
.action { color: #b362ff; }
.mode, .nick, .topic, .server { color: #80ffbb; }
.highlight { color: #e1efff; background-color: #7d44b2; border-left: 3px solid #b362ff; padding-left: 8px; }
.reply { color: #b362ff; border-left: 2px solid #9effff; padding-left: 6px; }
.oper { color: #2d2b55; background-color: #fad000; }
.reactions { color: #9effff; background-color: #3b376e; }
.card { background-color: #3b376e; border-color: #b362ff; }
.card-title { color: #9effff; }
.card-desc { color: #b362ff; }
.daychange { color: #b362ff; border-color: #3b376e; }
